operational_health.original_command:
test -x /usr/local/bin/aws && python3 - <<'PY'
import concurrent.futures, datetime, json, subprocess, urllib.request
now=datetime.datetime.now(datetime.timezone.utc)
def aws(*args):
    return json.loads(subprocess.check_output(['/usr/local/bin/aws',*args,'--region','us-east-1','--output','json','--no-cli-pager'],text=True))
def service():
    s=aws('ecs','describe-services','--cluster','tfe-web-cluster','--services','dsf-ai-service-lb')['services'][0]
    arns=aws('ecs','list-tasks','--cluster','tfe-web-cluster','--service-name','dsf-ai-service-lb')['taskArns']
    tasks=aws('ecs','describe-tasks','--cluster','tfe-web-cluster','--tasks',*arns)['tasks'] if arns else []
    return {'counts':[s[k] for k in ('desiredCount','runningCount','pendingCount')], 'taskDefinition':s['taskDefinition'], 'tasks':[{'arn':t['taskArn'],'status':t['lastStatus'],'health':t.get('healthStatus'),'digests':[c.get('imageDigest') for c in t['containers']]} for t in tasks]}
def alarms():
    return [{'name':x['AlarmName'],'state':x['StateValue']} for x in aws('cloudwatch','describe-alarms','--alarm-name-prefix','guala')['MetricAlarms']]
def metric(name):
    r=aws('cloudwatch','get-metric-statistics','--namespace','AWS/ECS','--metric-name',name,'--dimensions','Name=ClusterName,Value=tfe-web-cluster','Name=ServiceName,Value=dsf-ai-service-lb','--start-time',(now-datetime.timedelta(minutes=10)).isoformat(),'--end-time',now.isoformat(),'--period','60','--statistics','Average','Maximum')
    return sorted(r['Datapoints'],key=lambda x:x['Timestamp'])[-1:]
def observation():
    with urllib.request.urlopen('https://dsf-ai.com/api/v1/guala/observation',timeout=20) as r: d=json.load(r)
    return {k:d.get(k) for k in ('available','identity','live_tick','persisted_tick','checkpoint_error','cleanup_error','durability_blocked')}
with concurrent.futures.ThreadPoolExecutor(max_workers=4) as p:
    jobs={k:p.submit(f) for k,f in [('service',service),('alarms',alarms),('cpu',lambda:metric('CPUUtilization')),('memory',lambda:metric('MemoryUtilization')),('observation',observation)]}
    print(json.dumps({'utc':now.isoformat(),**{k:v.result() for k,v in jobs.items()}}))
PY
